// PRODUTOS
let produtos = JSON.parse(localStorage.getItem("produtos")) || [];

// LOGIN
function login() {

    const usuario = document.getElementById("usuario").value;
        const senha = document.getElementById("senha").value;
            const erro = document.getElementById("erroLogin");

                if (usuario === "admin" && senha === "1234") {

                        document.getElementById("loginPage").style.display = "none";
                                document.getElementById("sistema").classList.remove("hidden");

                                        mostrarProdutos();

                                            } else {

                                                    erro.textContent = "Usuário ou senha incorretos.";
                                                        }
                                                        }

                                                        // LOGOUT
                                                        function logout() {

                                                            document.getElementById("sistema").classList.add("hidden");
                                                                document.getElementById("loginPage").style.display = "flex";

                                                                    document.getElementById("usuario").value = "";
                                                                        document.getElementById("senha").value = "";
                                                                        }

                                                                        // ADICIONAR PRODUTO
                                                                        function adicionarProduto() {

                                                                            const codigo = document.getElementById("codigo").value;
                                                                                const nome = document.getElementById("nome").value;
                                                                                    const categoria = document.getElementById("categoria").value;
                                                                                        const quantidade = Number(
                                                                                                document.getElementById("quantidade").value
                                                                                                    );
                                                                                                        const preco = Number(
                                                                                                                document.getElementById("preco").value
                                                                                                                    );

                                                                                                                        if (
                                                                                                                                codigo === "" ||
                                                                                                                                        nome === "" ||
                                                                                                                                                categoria === "" ||
                                                                                                                                                        quantidade === "" ||
                                                                                                                                                                preco === ""
                                                                                                                                                                    ) {
                                                                                                                                                                            alert("Preencha todos os campos.");
                                                                                                                                                                                    return;
                                                                                                                                                                                        }

                                                                                                                                                                                            const produto = {
                                                                                                                                                                                                    id: Date.now(),
                                                                                                                                                                                                            codigo: codigo,
                                                                                                                                                                                                                    nome: nome,
                                                                                                                                                                                                                            categoria: categoria,
                                                                                                                                                                                                                                    quantidade: quantidade,
                                                                                                                                                                                                                                            preco: preco
                                                                                                                                                                                                                                                };

                                                                                                                                                                                                                                                    produtos.push(produto);

                                                                                                                                                                                                                                                        salvarProdutos();

                                                                                                                                                                                                                                                            limparFormulario();

                                                                                                                                                                                                                                                                mostrarProdutos();

                                                                                                                                                                                                                                                                    alert("Produto cadastrado com sucesso!");
                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                    // SALVAR
                                                                                                                                                                                                                                                                    function salvarProdutos() {

                                                                                                                                                                                                                                                                        localStorage.setItem(
                                                                                                                                                                                                                                                                                "produtos",
                                                                                                                                                                                                                                                                                        JSON.stringify(produtos)
                                                                                                                                                                                                                                                                                            );
                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                            // LIMPAR FORMULÁRIO
                                                                                                                                                                                                                                                                                            function limparFormulario() {

                                                                                                                                                                                                                                                                                                document.getElementById("codigo").value = "";
                                                                                                                                                                                                                                                                                                    document.getElementById("nome").value = "";
                                                                                                                                                                                                                                                                                                        document.getElementById("categoria").value = "";
                                                                                                                                                                                                                                                                                                            document.getElementById("quantidade").value = "";
                                                                                                                                                                                                                                                                                                                document.getElementById("preco").value = "";
                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                // MOSTRAR PRODUTOS
                                                                                                                                                                                                                                                                                                                function mostrarProdutos() {

                                                                                                                                                                                                                                                                                                                    const tabela = document.getElementById("tabelaProdutos");

                                                                                                                                                                                                                                                                                                                        const pesquisa = document
                                                                                                                                                                                                                                                                                                                                .getElementById("pesquisa")
                                                                                                                                                                                                                                                                                                                                        .value
                                                                                                                                                                                                                                                                                                                                                .toLowerCase();

                                                                                                                                                                                                                                                                                                                                                    tabela.innerHTML = "";

                                                                                                                                                                                                                                                                                                                                                        let totalItens = 0;
                                                                                                                                                                                                                                                                                                                                                            let valorTotal = 0;
                                                                                                                                                                                                                                                                                                                                                                let produtosBaixoEstoque = 0;

                                                                                                                                                                                                                                                                                                                                                                    const produtosFiltrados = produtos.filter(produto => {

                                                                                                                                                                                                                                                                                                                                                                            return (
                                                                                                                                                                                                                                                                                                                                                                                        produto.nome.toLowerCase().includes(pesquisa) ||
                                                                                                                                                                                                                                                                                                                                                                                                    produto.codigo.toLowerCase().includes(pesquisa) ||
                                                                                                                                                                                                                                                                                                                                                                                                                produto.categoria.toLowerCase().includes(pesquisa)
                                                                                                                                                                                                                                                                                                                                                                                                                        );

                                                                                                                                                                                                                                                                                                                                                                                                                            });

                                                                                                                                                                                                                                                                                                                                                                                                                                produtosFiltrados.forEach(produto => {

                                                                                                                                                                                                                                                                                                                                                                                                                                        const totalProduto =
                                                                                                                                                                                                                                                                                                                                                                                                                                                    produto.quantidade * produto.preco;

                                                                                                                                                                                                                                                                                                                                                                                                                                                            totalItens += produto.quantidade;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    valorTotal += totalProduto;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (produto.quantidade <= 5) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        produtosBaixoEstoque++;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const linha = document.createElement("tr");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                linha.innerHTML = `
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <td>${produto.codigo}</td>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <td>${produto.nome}</td>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <td>${produto.categoria}</td>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ${produto.quantidade}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </td>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ${formatarMoeda(produto.preco)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </td>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ${formatarMoeda(totalProduto)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </td>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <button
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            class="btn-excluir"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                onclick="excluirProduto(${produto.id})">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Excluir
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        `;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                tabela.appendChild(linha);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        document.getElementById("totalProdutos").textContent =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                produtos.length;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    document.getElementById("totalItens").textContent =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            totalItens;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                document.getElementById("valorEstoque").textContent =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        formatarMoeda(valorTotal);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            document.getElementById("estoqueBaixo").textContent =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    produtosBaixoEstoque;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // EXCLUIR
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    function excluirProduto(id) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const confirmar = confirm(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                "Deseja realmente excluir este produto?"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (!confirmar) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        produtos = produtos.filter(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                produto => produto.id !== id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        salvarProdutos();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            mostrarProdutos();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // FORMATAÇÃO DE MOEDA
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            function formatarMoeda(valor) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return valor.toLocaleString("pt-BR", {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        style: "currency",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                currency: "BRL"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }